L["Spell icons"] = "Icone degli incantesimi"
L["Spell range"] = "Portata degli incantesimi"
L["Spin, speeding up to %s°/s, for %s s"] = "Gira, accelerando fino a %s°/s, per %s s"
L["Spin, speeding up to %s°/s, until it ends"] = "Gira, accelerando fino a %s°/s, finché non finisce"
L["Spiral arms"] = "Bracci a spirale"
L["Spiraling motes"] = "Granelli a spirale"
L["Square"] = "Quadrato"
